<script setup lang="ts">
import type { Report } from '~/types/lapormas'
definePageMeta({ layout: 'app', middleware: 'auth', title: 'Detail Laporan' })
const route = useRoute()
const { state, currentUser, deleteReport, verifyReport, takeReport, resolveReport, updateResolution, deleteResolution } = useLaporMas()
const report = computed(() => state.value.reports.find(r => r.id === route.params.id) as Report | undefined)
const user = computed(() => currentUser.value!)
const isOwner = computed(() => !!report.value && report.value.ownerId === user.value?.id)
const isAdmin = computed(() => user.value?.role === 'admin')
const isOfficer = computed(() => user.value?.role === 'petugas')
const isVisible = computed(() => !!report.value && (isOwner.value || isAdmin.value || isOfficer.value || user.value?.role === 'rt' && !['Menunggu verifikasi', 'Ditolak'].includes(report.value.status)))
const resolutionText = ref('')
const reviewNote = ref('')
const editResolutionMode = ref(false)
const showResolution = ref(false)
const toast = ref('')
watch(report, value => { resolutionText.value = value?.resolution?.summary || '' }, { immediate: true })
const formatDate = (value: string) => new Intl.DateTimeFormat('id-ID', { dateStyle: 'long', timeStyle: 'short' }).format(new Date(value))
function verify(approved: boolean) { if (!report.value) return; if (verifyReport(report.value.id, approved, reviewNote.value)) { toast.value = approved ? 'Laporan berhasil diverifikasi.' : 'Laporan ditolak dan catatan dikirim ke pelapor.'; reviewNote.value = '' } }
function take() { if (report.value && takeReport(report.value.id)) toast.value = 'Laporan masuk ke antrean penanganan Anda.' }
function saveResolution() {
  if (!report.value) return
  const ok = report.value.resolution && editResolutionMode.value ? updateResolution(report.value.id, resolutionText.value) : resolveReport(report.value.id, resolutionText.value)
  if (ok) { toast.value = 'Hasil penanganan berhasil disimpan.'; showResolution.value = false; editResolutionMode.value = false }
}
function remove() { if (!report.value) return; if (window.confirm('Hapus laporan ini dari data prototipe?')) { deleteReport(report.value.id); navigateTo(user.value.role === 'admin' ? '/admin' : '/app/laporan') } }
function removeResolution() { if (!report.value || !window.confirm('Hapus catatan hasil penanganan? Status akan kembali menjadi Ditangani.')) return; deleteResolution(report.value.id); toast.value = 'Catatan penyelesaian dihapus.' }
async function copyTicket() { if (!report.value) return; try { await navigator.clipboard.writeText(report.value.ticket); toast.value = 'Nomor tiket berhasil disalin.' } catch { toast.value = 'Tidak dapat mengakses clipboard pada browser ini.' } }
</script>
<template>
  <div v-if="report && isVisible" class="page-stack"><div class="page-title-row detail-title-row"><div><NuxtLink to="/app/laporan" class="back-link">← Kembali ke daftar</NuxtLink><div class="eyebrow">DETAIL ADUAN · {{ report.ticket }}</div><h1>{{ report.title }}</h1><p>Dikirim {{ formatDate(report.createdAt) }} oleh {{ isOwner ? 'Anda' : isAdmin ? report.ownerName : 'Warga komplek' }}</p></div><div class="detail-title-actions"><StatusBadge :status="report.status"/><button v-if="isOwner || isAdmin" class="btn btn-ghost btn-small" @click="remove">Hapus</button></div></div>
    <div v-if="toast" class="success-banner"><span>✓</span>{{ toast }}<button @click="toast = ''">×</button></div>
    <div class="detail-layout"><div class="detail-main"><section class="panel detail-panel"><div class="detail-meta-grid"><div><small>KATEGORI</small><b>{{ report.category }}</b></div><div><small>URGENSI</small><b><span class="priority" :class="`priority-${report.priority.toLowerCase()}`">{{ report.priority }}</span></b></div><div><small>WAKTU KEJADIAN</small><b>{{ formatDate(report.occurredAt) }}</b></div><div><small>LOKASI</small><b>{{ report.location }}</b></div></div><div class="detail-divider"></div><h3>Deskripsi kejadian</h3><p class="detail-description">{{ report.description }}</p><div v-if="report.attachments.length" class="detail-attachments"><b>Lampiran pendukung</b><div class="attachment-list"><div v-for="file in report.attachments" :key="file" class="attachment-item"><span>▧</span><b>{{ file }}</b></div></div><small class="field-hint">Prototipe menyimpan nama lampiran; file tidak diunggah ke server.</small></div><div v-if="report.adminNote" class="admin-note"><b>Catatan admin</b><p>{{ report.adminNote }}</p></div></section>
      <section v-if="report.resolution" class="panel resolution-panel"><div class="panel-heading"><div><div class="eyebrow">HASIL TINDAK LANJUT</div><h3>Penanganan laporan</h3></div><span class="resolution-check">✓</span></div><p>{{ report.resolution.summary }}</p><div class="resolution-byline">Diperbarui oleh <b>{{ report.resolution.officerName }}</b> · {{ formatDate(report.resolution.createdAt) }}</div><div v-if="isOfficer" class="inline-actions"><button class="btn btn-outline btn-small" @click="editResolutionMode = true; showResolution = true">Edit hasil</button><button class="btn btn-ghost btn-small danger-text" @click="removeResolution">Hapus hasil</button></div></section>
      <section v-if="isOfficer && (showResolution || editResolutionMode)" class="panel action-panel"><div class="panel-heading"><div><h3>{{ editResolutionMode ? 'Perbarui hasil penanganan' : 'Catat hasil penanganan' }}</h3><p>Jelaskan tindakan dan kondisi akhir secara ringkas.</p></div></div><textarea v-model="resolutionText" class="text-input textarea" rows="4" placeholder="Contoh: Petugas melakukan pemeriksaan lokasi dan memperbaiki lampu penerangan..."/><div class="inline-actions"><button class="btn btn-primary" :disabled="!resolutionText.trim()" @click="saveResolution">Simpan hasil</button><button class="btn btn-ghost" @click="editResolutionMode = false; showResolution = false">Batal</button></div></section>
      <section class="panel timeline-panel"><div class="panel-heading"><div><h3>Riwayat laporan</h3><p>Setiap pembaruan status tercatat di sini.</p></div></div><div class="timeline"><div v-for="(event, index) in [...report.events].sort((a,b) => a.createdAt.localeCompare(b.createdAt))" :key="event.id" class="timeline-item" :class="{ last: index === report.events.length - 1 }"><span class="timeline-marker">{{ index + 1 }}</span><div><b>{{ event.label }}</b><p>{{ event.description }}</p><small>{{ event.actorName }} · {{ formatDate(event.createdAt) }}</small></div></div></div></section></div>
      <aside class="detail-aside"><section class="panel action-panel"><div class="eyebrow">TINDAKAN</div><h3>{{ isAdmin ? 'Pemeriksaan admin' : isOfficer ? 'Panel petugas' : 'Informasi laporan' }}</h3><template v-if="isAdmin && report.status === 'Menunggu verifikasi'"><p>Periksa kelengkapan informasi sebelum laporan ditampilkan kepada warga.</p><label class="field-label">Catatan pemeriksaan <textarea v-model="reviewNote" class="text-input textarea" rows="3" placeholder="Opsional: alasan penolakan atau catatan verifikasi"/></label><button class="btn btn-primary btn-full" @click="verify(true)">✓ Verifikasi laporan</button><button class="btn btn-outline btn-full danger-outline" @click="verify(false)">Tolak laporan</button></template><template v-else-if="isOfficer && report.status === 'Terverifikasi'"><p>Laporan telah diverifikasi admin dan siap ditindaklanjuti.</p><button class="btn btn-primary btn-full" @click="take">Ambil penanganan →</button></template><template v-else-if="isOfficer && report.status === 'Ditangani'"><p>Catat hasil setelah petugas melakukan tindakan di lapangan.</p><button class="btn btn-primary btn-full" @click="showResolution = true">+ Catat hasil penyelesaian</button></template><template v-else-if="isOwner && report.status === 'Menunggu verifikasi'"><p>Laporan sedang menunggu pemeriksaan admin. Anda masih dapat memperbarui informasi.</p><NuxtLink :to="`/app/laporan/buat?edit=${report.id}`" class="btn btn-outline btn-full">Edit laporan</NuxtLink></template><template v-else-if="isOwner && report.status === 'Ditolak'"><p>Laporan belum dapat diverifikasi. Baca catatan admin, perbaiki informasi, lalu kirim kembali.</p><NuxtLink :to="`/app/laporan/buat?edit=${report.id}`" class="btn btn-primary btn-full">Perbaiki laporan</NuxtLink></template><template v-else><p>{{ report.status === 'Selesai' ? 'Penanganan telah ditandai selesai oleh petugas.' : 'Informasi terbaru akan muncul saat status laporan diperbarui.' }}</p></template></section><section class="privacy-note"><span>◈</span><div><b>Privasi pelapor</b><p>Identitas pelapor tidak ditampilkan pada ringkasan publik. Hindari membagikan informasi pribadi dalam deskripsi.</p></div></section><section class="panel ticket-panel"><small>NOMOR TIKET</small><strong>{{ report.ticket }}</strong><button class="copy-ticket" @click="copyTicket">Salin nomor ↗</button></section></aside></div>
  </div><EmptyState v-else title="Laporan tidak ditemukan" description="Laporan mungkin telah dihapus atau Anda tidak memiliki akses untuk melihatnya." icon="⌕"><NuxtLink to="/app/laporan" class="btn btn-outline btn-small">Kembali ke laporan</NuxtLink></EmptyState>
</template>
